    name: str | None,
    *,
    region: str,
    tofu_dir: str,
    connectivity: str | None = None,
) -&gt; ComputeProvider:
    name = name or DEFAULT_PROVIDER
    providers = _discover()
    cls = providers.get(name)
    if cls is None:
        raise ValueError(
            f"unknown provider '{name}'; available: {sorted(providers)}"
        )
    if name == "manual":
        conn_name = connectivity or "lan_direct"
        conn_cls = _CONNECTIVITY_BUILTIN.get(conn_name)
        if conn_cls is None:
            raise ValueError(
                f"unknown connectivity '{conn_name}'; "
                f"available: {sorted(_CONNECTIVITY_BUILTIN)}"
            )
        return cls(
            region=region,
            tofu_dir=tofu_dir,
            client_connectivity=conn_cls(),
        )
    return cls(region=region, tofu_dir=tofu_dir)
