Source code in <code>packages/client/src/lablink_client_service/agent/api.py</code> <pre><code>def create_app() -&gt; Flask:
    app = Flask(__name__)
    expected = os.environ.get("AGENT_TOKEN", "")

    @app.post("/api/session/start")
    def session_start():
        # Constant-time-ish check: short-circuit on the prefix to keep
        # the path uniform-ish for malformed headers, then compare the
        # token. We don't bother with hmac.compare_digest because the
        # token's already randomly generated and the agent is one-call-
        # per-seat — timing-channel risk is negligible.
        auth = request.headers.get("Authorization", "")
        if not expected:
            logger.error("AGENT_TOKEN env var is not set; rejecting all calls")
            return jsonify(error="server misconfigured"), 500
        if not auth.startswith("Bearer ") or auth[7:] != expected:
            return jsonify(error="unauthorized"), 401

        body = request.get_json(silent=True) or {}
        password = body.get("password")
        if not password:
            return jsonify(error="password required"), 400

        try:
            rotate_kasmvnc_password(password=password)
        except Exception as exc:
            logger.exception("KasmVNC password rotation failed")
            return jsonify(error=f"rotation failed: {exc}"), 500

        # Anchor the monitoring agent's session clock at user-assignment
        # time. A write failure here is non-fatal: the seat is usable;
        # only metric timing is affected (clock will stay at last anchor
        # or at agent boot if none has been written yet).
        try:
            write_anchor(datetime.now(timezone.utc))
        except OSError:
            logger.exception(
                "Failed to write session anchor; metrics may be misaligned"
            )

        return jsonify(ok=True), 200

    @app.get("/healthz")
    def healthz():
        return "ok", 200

    return app
</code></pre>

Source code in <code>packages/client/src/lablink_client_service/monitoring/aggregator.py</code> <pre><code>def apply_sample(c: SessionCounters, s: Sample) -&gt; None:
    c.sample_count += 1

    bucket = (
        s.active_window_bucket if s.active_window_bucket in WINDOW_BUCKETS else "other"
    )
    attr = SUBJECT_FIELD if bucket == "subject" else f"seconds_in_{bucket}"
    setattr(c, attr, getattr(c, attr) + s.sample_interval_seconds)

    if s.gpu_util_pct &gt; GPU_ACTIVE_UTIL_THRESHOLD:
        c.gpu_active_seconds += s.sample_interval_seconds
    if s.gpu_util_pct &gt; c.gpu_util_peak:
        c.gpu_util_peak = s.gpu_util_pct
    if s.vram_mb &gt; c.vram_used_peak_mb:
        c.vram_used_peak_mb = s.vram_mb

    elapsed = int((s.ts - c.session_started_at).total_seconds())
    if "sleap-label" in s.processes_seen and c.seconds_to_first_sleap_label is None:
        c.seconds_to_first_sleap_label = elapsed
    if "sleap-train" in s.processes_seen and c.seconds_to_first_sleap_train is None:
        c.seconds_to_first_sleap_train = elapsed
    if "sleap-track" in s.processes_seen and c.seconds_to_first_sleap_track is None:
        c.seconds_to_first_sleap_track = elapsed

    if s.max_labeled_frames is not None and s.max_labeled_frames &gt; c.max_labeled_frames:
        c.max_labeled_frames = s.max_labeled_frames
    if (
        s.training_epochs_completed is not None
        and s.training_epochs_completed &gt; c.training_epochs_completed
    ):
        c.training_epochs_completed = s.training_epochs_completed
    if s.training_final_loss is not None:
        c.training_final_loss = s.training_final_loss
