Source code in <code>packages/client/src/lablink_client_service/monitoring/samplers/gpu.py</code> <pre><code>def sample() -&gt; tuple[int, int]:
    try:
        out = subprocess.run(
            [
                "nvidia-smi",
                "--query-gpu=utilization.gpu,memory.used",
                "--format=csv,noheader,nounits",
            ],
            capture_output=True,
            text=True,
            timeout=2,
        )
    except (FileNotFoundError, subprocess.TimeoutExpired) as e:
        logger.debug("nvidia-smi probe failed: %s", e)
        return 0, 0

    if out.returncode != 0:
        return 0, 0
    line = out.stdout.strip().splitlines()[0] if out.stdout.strip() else ""
    if not line:
        return 0, 0
    try:
        util_s, vram_s = (p.strip() for p in line.split(","))
        return int(util_s), int(vram_s)
    except (ValueError, IndexError) as e:
        logger.debug("nvidia-smi parse failed (%r): %s", line, e)
        return 0, 0
</code></pre>

Source code in <code>packages/client/src/lablink_client_service/monitoring/samplers/processes.py</code> <pre><code>def sample(allowlist: Iterable[str], proc_root: str = "/proc") -&gt; Set[str]:
    wanted = set(allowlist)
    seen: Set[str] = set()
    try:
        entries = os.listdir(proc_root)
    except OSError:
        return seen

    for name in entries:
        if not name.isdigit():
            continue
        parts = _read_cmdline(os.path.join(proc_root, name, "cmdline"))
        if parts is None:
            continue
        seen |= _classify(parts, wanted)
        if seen &gt;= wanted:
            break
    return seen
</code></pre>
